// @ts-check
// The requirement-symbol artifact on the build path (ADR-0056: "a build input, regenerated by the test session before
// collection, so the build and the test runner share one generator").
//
// `packages/kernel/src/index.ts` re-exports `./generated/requirements.js`, which is git-ignored, so a tree that neither
// the gate nor a test session has touched had no artifact and `electron-vite build` stopped at rollup naming the module
// and not the command that writes it (docs/defects/fixed/a-fresh-clone-cannot-build-until-pnpm-symbols-has-run.md).
//
// The shape ADR-0056 asks for: the build runs the SAME generator the test session runs (`generate.mjs`, a child
// process exactly as `global-setup.ts` starts it), so there is still one generator and nothing to drift. The build
// generates only when the artifact is ABSENT. Keeping it current stays where ADR-0056 put it, with the test session and
// `pnpm symbols` (the gate's first stage); the build does not take that role over, and does not repeat a generation
// those already did. What it costs: one `existsSync` on every build; once in a tree's life, one generator run (about
// 0.2 s on the Linux host, 2026-10-31: it reads docs/spec and docs/product, not the tree). Regenerating on every build
// was not chosen: the cost is the same order, but each build would then replace the file a concurrent test session may
// be replacing too, the case REQ-TRACE-061's ladder exists for (constraint D-06), and `pnpm dev` would rewrite a module
// it is watching.
//
// Unlike the test session's regeneration, which REQ-TRACE-182 forbids from blocking collection, a failure here FAILS
// the build, loudly: without the artifact the build cannot succeed anyway, and the message names the file and the
// command, which the rollup error did not. An exit 0 that leaves no file is a failure too (ADR-0056 rule 1a's lesson:
// an exit status is not evidence that anything was written).

import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';

/**
 * Write the artifact with the generator when it does not exist; do nothing when it does.
 *
 * @param {{ artifact: string, generator: string }} paths both absolute
 * @returns {{ generated: boolean }}
 */
export function ensureSymbolArtifact({ artifact, generator }) {
  if (existsSync(artifact)) return { generated: false };
  const command = `pnpm symbols (node ${generator})`;
  try {
    execFileSync(process.execPath, [generator], { stdio: 'inherit' });
  } catch (cause) {
    throw new Error(
      `symbol artifact: ${artifact} is missing and ${command} could not write it — ${cause instanceof Error ? cause.message : String(cause)}. Every build imports it through packages/kernel/src/index.ts; run \`pnpm symbols\` and repair what it reports.`,
    );
  }
  if (!existsSync(artifact)) {
    throw new Error(`symbol artifact: ${command} exited 0 and ${artifact} still does not exist; every build imports it through packages/kernel/src/index.ts.`);
  }
  return { generated: true };
}

/**
 * The same, as a Vite plugin: electron-vite runs `buildStart` before any module of a section is resolved, in `build`,
 * in `dev` and in `pnpm package`'s own `electron-vite build`. The first section to start writes the artifact; the
 * others find it. `api` (Vite's field for what a plugin exposes) carries the paths, so a test can hold the config to the
 * artifact the kernel imports.
 *
 * @param {{ artifact: string, generator: string }} paths
 */
export function symbolArtifactPlugin(paths) {
  return {
    name: 'rotaris:symbol-artifact',
    api: { paths },
    buildStart() {
      ensureSymbolArtifact(paths);
    },
  };
}
